#include <iostream>
#include <string>
#include <algorithm>
#include <vector>

int maxLength(const std::string& s) {
    std::string t;
    bool inside = false;
    for (size_t i = 0; i < s.length(); ++i) {
        char ch = s[i];
        if (ch == '(')
            inside = true;
        else if (ch == ')') {
            inside = false;
            t += '_';
        }
        if (!inside && ch != ')')
            t += ch;
    }
    int max_len = 0;
    size_t start = 0;
    while (true) {
        size_t pos = t.find('_', start);
        std::string part = t.substr(start, pos - start);
        max_len = std::max(max_len, static_cast<int>(part.length()));
        if (pos == std::string::npos)
            break;
        start = pos + 1;
    }
    return max_len;
}

int count(const std::string& s) {
    int cnt = 0;
    size_t start = 0;
    while (true) {
        size_t pos = s.find('_', start);
        std::string part = s.substr(start, pos - start);
        if (!part.empty())
            ++cnt;
        if (pos == std::string::npos)
            break;
        start = pos + 1;
    }
    return cnt;
}

int words(const std::string& s) {
    int total = 0;
    std::string t;
    bool inside = false;
    for (size_t i = 0; i < s.length(); ++i) {
        char ch = s[i];
        if (ch == '(')
            inside = true;
        else if (ch == ')') {
            inside = false;
            total += count(t);
            t.clear();
        }
        if (inside && ch != '(')
            t += ch;
    }
    return total;
}

int main() {
    int n;
    std::cin >> n;
